<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\WebsiteSetting;use Illuminate\Http\Request;
class SettingsController extends Controller { public function index(){return response()->json(['data'=>WebsiteSetting::pluck('value','key')]);} public function update(Request $r){$d=$r->validate(['business_name'=>'nullable|string|max:190','phone'=>'nullable|string|max:60','email'=>'nullable|email|max:190','whatsapp'=>'nullable|string|max:60','address'=>'nullable|string|max:1000','currency'=>'nullable|string|max:10','business_hours'=>'nullable|string|max:500','ga4_id'=>'nullable|string|max:190','gtm_id'=>'nullable|string|max:190','google_ads_id'=>'nullable|string|max:190','meta_pixel_id'=>'nullable|string|max:190']);foreach($d as $key=>$value)WebsiteSetting::updateOrCreate(['key'=>$key],['value'=>$value,'group'=>str_contains($key,'id')?'analytics':'general','is_public'=>in_array($key,['business_name','phone','email','whatsapp','address','currency','business_hours'])]);return response()->json(['message'=>'Settings saved.','data'=>WebsiteSetting::pluck('value','key')]);} }
